115:     for (const key of Object.keys(SKILLS)) {
116:       if (!p.skills[key]) p.skills[key] = { level: 0, xp: 0, next: this.skillNext(0) };
117:     }
118:     p.xpBonus = bg.xpBonus || 0;
119:     const startItems = (bg.items || []).map(([id, qty]) => ({ id, qty, condition: 1 }));
120:     // Itens básicos garantidos
121:     if (!startItems.some(i => ITEMS[i.id]?.type === 'drink')) startItems.push({ id: 'agua', qty: 1, condition: 1 });
122:     if (!startItems.some(i => ITEMS[i.id]?.type === 'food')) startItems.push({ id: 'enlatado', qty: 1, condition: 1 });
123:     if (!startItems.some(i => ITEMS[i.id]?.weapon)) startItems.push({ id: 'bastao', qty: 1, condition: 0.8 });
124:     if (!startItems.some(i => ITEMS[i.id]?.type === 'med')) startItems.push({ id: 'bandagem', qty: 1, condition: 1 });
125:     for (const it of startItems) this.pushItem(p.inventory, it);
126:     const weapon = p.inventory.find(s => ITEMS[s.id]?.weapon);
127:     if (weapon) weapon.equipped = true;
128:     const pack = p.inventory.find(s => ITEMS[s.id]?.type === 'backpack');
129:     if (pack) pack.equipped = true;
130:     for (const s of p.inventory) if (ITEMS[s.id]?.type === 'clothing' && chance(this.world.rng, 0.4)) s.equipped = true;
131:     p.capacity = this.calcCapacity(p);
132:     return p;
133:   }
134: 
135:   skillNext(level) { return Math.round(55 * Math.pow(1.32, level)); }
136: 
137:   get weaponStack() { return this.player.inventory.find(s => s.equipped && ITEMS[s.id]?.weapon); }
138:   get backpackStack() { return this.player.inventory.find(s => s.equipped && ITEMS[s.id]?.type === 'backpack'); }
139:   get clothingStacks() { return this.player.inventory.filter(s => s.equipped && ITEMS[s.id]?.type === 'clothing'); }
140: 
141:   calcCapacity(p = this.player) {
142:     let c = BASE_CAPACITY + (p.skills.condicionamento?.level || 0) * 0.35;
143:     const pack = p.inventory.find(s => s.equipped && ITEMS[s.id]?.type === 'backpack');
144:     if (pack) c += ITEMS[pack.id].capacity || 0;
145:     return Math.round(c * 10) / 10;
146:   }
147: 
148:   weight(inv = this.player.inventory) {
149:     let w = 0;
150:     for (const s of inv) w += (ITEMS[s.id]?.weight || 0) * (s.qty || 1);
151:     return Math.round(w * 100) / 100;
152:   }
153: 
154:   capacity() { this.player.capacity = this.calcCapacity(); return this.player.capacity; }
155: 
156:   pushItem(inv, item) {
157:     const def = ITEMS[item.id];
158:     if (!def) return false;
159:     if (def.stack > 1) {
160:       const existing = inv.find(s => s.id === item.id && s.qty < def.stack && !s.equipped);
161:       if (existing) {
162:         const can = Math.min(def.stack - existing.qty, item.qty);
163:         existing.qty += can;
164:         item.qty -= can;
165:         if (item.qty <= 0) return true;
166:       }
167:     }
168:     inv.push({ ...item });
169:     return true;
170:   }
171: 
172:   addItem(id, qty = 1, condition = 1, opts = {}) {
173:     if (!ITEMS[id] || qty <= 0) return false;
174:     const def = ITEMS[id];
175:     const addWeight = def.weight * qty;
176:     if (!opts.ignoreWeight && this.weight() + addWeight > this.capacity() * 1.1) {
177:       this.ui?.notify('Carga máxima atingida. Solte algo ou use uma mochila.', 'warn', '⚖️');
178:       return false;
179:     }
180:     this.pushItem(this.player.inventory, { id, qty, condition });
181:     this.player.capacity = this.calcCapacity();
182:     if (opts.silent !== true) audio.play('pickup');
183:     return true;
184:   }
185: 
186:   removeItem(id, qty = 1) {
187:     let need = qty;
188:     const inv = this.player.inventory;
189:     for (let i = inv.length - 1; i >= 0 && need > 0; i--) {
190:       if (inv[i].id !== id) continue;
191:       const take = Math.min(inv[i].qty, need);
192:       inv[i].qty -= take; need -= take;
193:       if (inv[i].qty <= 0) inv.splice(i, 1);
194:     }
195:     this.player.capacity = this.calcCapacity();
196:     return need === 0;
197:   }
198: 
199:   countItem(id) {
200:     return this.player.inventory.filter(s => s.id === id).reduce((a, s) => a + s.qty, 0);
201:   }
202: 
203:   hasTool(...ids) { return ids.some(id => this.countItem(id) > 0); }
