211:   spawnInitialZombies() {
212:     const rng = this.world.rng;
213:     const target = Math.round(95 * this.diff.spawn);
214:     const start = this.player;
215:     const anchors = shuffle(rng, this.world.spawnPoints.slice());
216:     let placed = 0;
217:     const near = anchors.filter(p => dist(p.x, p.y, start.x, start.y) < 1900 && dist(p.x, p.y, start.x, start.y) > 430);
218:     const far = anchors.filter(p => dist(p.x, p.y, start.x, start.y) >= 1900);
219:     const pool = [...near, ...far];
220:     for (const a of pool) {
221:       if (placed >= target) break;
222:       if (this.zombies.some(z => dist(z.x, z.y, a.x, a.y) < 45)) continue;
223:       if (dist(a.x, a.y, start.x, start.y) < 420) continue;
224:       this.spawnZombie(a.x, a.y, this.pickZombieType());
225:       placed++;
226:     }
227:     // alguns dentro de prédios
228:     for (const b of this.world.buildings) {
229:       if (placed >= target + 12) break;
230:       if (chance(rng, 0.45) && dist((b.x + b.w / 2) * TILE, (b.y + b.h / 2) * TILE, start.x, start.y) > 600) {
231:         const spot = { x: (b.x + 1.5 + rng() * (b.w - 3)) * TILE, y: (b.y + 1.5 + rng() * (b.h - 3)) * TILE };
232:         if (!this.world.collidesCircle(spot.x, spot.y, 10)) { this.spawnZombie(spot.x, spot.y, this.pickZombieType()); placed++; }
233:       }
234:     }
235:   }
