237:   pickZombieType() {
238:     const day = this.day;
239:     const entries = [
240:       ['comum', 68], ['corredor', 12 + Math.min(20, day * 2.2)],
241:       ['rastejante', 11], ['bruto', 3 + Math.min(16, day * 1.8)],
242:     ];
243:     let total = entries.reduce((s, e) => s + e[1], 0), r = this.world.rng() * total;
244:     for (const [type, w] of entries) { r -= w; if (r <= 0) return type; }
245:     return 'comum';
246:   }
