252:       type, hp: def.hp * (this.difficulty === 'apocalipse' ? 1.2 : 1), maxHp: def.hp,
253:       speed: def.speed * randRange(this.world.rng, 0.9, 1.12),
254:       damage: def.damage * this.diff.damage, size: def.size,
255:       hearing: def.hearing, sight: def.sight,
256:       state: 'idle', alert: 0, target: null, wander: null, idleTimer: randRange(this.world.rng, 0.5, 4),
257:       attackCd: 0, anim: this.world.rng() * 10, groanCd: randRange(this.world.rng, 3, 12),
258:       home: { x, y }, stuck: 0, lastX: x, lastY: y, hitFlash: 0, trapCd: 0,
259:       inside: false, xp: def.xp, corpseTimer: 0,
260:     };
261:     this.zombies.push(z);
262:     return z;
263:   }
