265:   spawnInitialNPCs() {
266:     const rng = this.world.rng;
267:     const pts = this.world.npcPoints.filter(p => dist(p.x, p.y, this.player.x, this.player.y) < 3400);
268:     const count = 11;
269:     const used = new Set();
270:     for (let i = 0; i < count && pts.length; i++) {
271:       const pt = pts[Math.floor(rng() * pts.length)];
272:       const spot = this.world.randomWalkableNear(pt.x, pt.y, 240);
