275:       if (used.has(key)) continue;
276:       used.add(key);
277:       this.spawnNPC(spot.x, spot.y, {
278:         name: choose(rng, SURVIVOR_FIRST) + ' ' + choose(rng, SURVIVOR_LAST),
279:         personality: choose(rng, ['cauteloso', 'amigável', 'desconfiado', 'prático', 'nervoso']),
280:         hostile: false,
281:       });
282:     }
283:     // um comerciante perto do início
284:     const near = this.world.randomWalkableNear(this.player.x, this.player.y, 700);
285:     this.spawnNPC(near.x, near.y, {
286:       name: 'Mercador ' + choose(rng, SURVIVOR_FIRST), personality: 'prático', hostile: false, trader: true,
287:       line: 'Tenho coisas que você precisa. Você tem coisas que eu quero.',
288:     });
