299:       attackCd: 0, weapon: opts.hostile ? 'cano' : (rng() < 0.5 ? 'faca' : 'bastao'),
300:       line: opts.line || choose(rng, TRADE_LINES), following: false, talked: false,
301:       trade: [], greeting: choose(rng, ['Ainda estou vivo. Por enquanto.', 'Cuidado lá fora.', 'Você tem comida?', 'Não confio em estranhos. Mas fale.']),
302:       anim: rng() * 10, hitFlash: 0, alive: true, combatSkill: opts.hostile ? 2 : skill,
