305:     for (let i = 0; i < (opts.trader ? 5 : 3); i++) {
306:       npc.trade.push(this.world.rollLoot(choose(this.world.rng, ['mercado', 'ferramentas', 'farmacia', 'armario', 'oficina']), 0.75)[0] || { id: 'bandagem', qty: 1, condition: 1 });
307:     }
308:     this.npcs.push(npc);
309:     return npc;
