312:   // ================= LOOP =================
313:   update(dt) {
314:     if (this.paused) return;
315:     if (!this.dead) {
316:       this.clock += dt;
317:       this.updateTime(dt);
318:       this.updateSurvival(dt);
319:       this.updatePlayer(dt);
320:       this.updateNoiseRings(dt);
321:       this.updateParticles(dt);
322:       this.updateFloaters(dt);
323:       this.updateZombies(dt);
324:       this.updateNPCs(dt);
325:       this.updateVehicles(dt);
326:       this.updateStructures(dt);
327:       this.updateEvents(dt);
328:       this.updateRemote(dt);
329:       this.updateObjectives();
330:       this.updateAutosave(dt);
331:       if (this.ui?.hudDirty) this.ui.refreshHUD();
332:     } else {
333:       this.updateParticles(dt * 0.35);
334:     }
335:     this.shake = Math.max(0, this.shake - dt * 18);
336:     this.hurtFlash = Math.max(0, this.hurtFlash - dt * 2.2);
337:     this.flash = Math.max(0, this.flash - dt * 2.5);
338:   }
339: 
340:   updateTime(dt) {
341:     this.timeAlive += dt;
342:     this.advanceTime(dt * TIME_RATE);
343:     if (this.weather === 'tempestade' && chance(this.world.rng, dt * 0.05)) {
344:       this.flash = 0.7 + Math.random() * 0.3;
345:       setTimeout(() => audio.play('thunder'), 300 + Math.random() * 500);
346:     }
347:   }
348: 
349:   advanceTime(minutes) {
350:     this.time += minutes;
351:     while (this.time >= 1440) {
352:       this.time -= 1440;
353:       this.day++;
354:       this.stats.days = this.day;
355:       this.onNewDay();
356:     }
357:     this.weatherTimer -= minutes;
358:     if (this.weatherTimer <= 0) this.changeWeather();
359:     this.seasonIndex = Math.floor((this.day - 1) / 7) % 4;
360:   }
361: 
362:   onNewDay() {
363:     const season = SEASONS[this.seasonIndex];
364:     this.ui?.notify(`Dia ${this.day} começou. ${season.icon} ${season.desc}`, 'day', '🌅');
365:     this.ui?.dayBanner(this.day, season, this.weather);
366:     // espalha novos zumbis com o tempo
367:     const cap = Math.round(140 * this.diff.spawn);
368:     if (this.isHost && this.zombies.length < cap) {
369:       const adds = Math.min(8, cap - this.zombies.length);
370:       for (let i = 0; i < adds; i++) {
371:         const p = this.world.randomWalkableNear(this.player.x + randRange(this.world.rng, -1400, 1400), this.player.y + randRange(this.world.rng, -1400, 1400), 300);
372:         if (dist(p.x, p.y, this.player.x, this.player.y) > 550) this.spawnZombie(p.x, p.y, this.pickZombieType());
373:       }
374:     }
375:     if (!this.flags.firstNightSurvived && this.day >= 2) {
376:       this.flags.firstNightSurvived = true;
377:       this.completeObjective('night');
378:     }
379:     // saque parcial em contêineres não visitados
380:     for (const c of this.world.containers) {
381:       if (!c.searched && chance(this.world.rng, 0.03)) c.items = this.world.rollLoot(c.type === 'caixa_suprimentos' ? 'caixa_suprimentos' : (c.type || 'caixa'), 0.5);
382:     }
383:     this.stats.days = this.day;
384:   }
385: 
386:   changeWeather() {
387:     const season = SEASONS[this.seasonIndex];
388:     const entries = [
389:       ['limpo', 36], ['nublado', 26], ['chuva', Math.round(season.rain * 100)],
390:       ['tempestade', Math.round(season.rain * 45)], ['neblina', 10 + season.rain * 12],
391:     ];
392:     let total = entries.reduce((s, e) => s + e[1], 0), r = Math.random() * total;
393:     let next = 'limpo';
394:     for (const [w, weight] of entries) { r -= weight; if (r <= 0) { next = w; break; } }
395:     if (next !== this.weather) {
396:       this.weather = next;
397:       const def = WEATHERS[next];
398:       this.ui?.notify(`Clima mudou: ${def.icon} ${def.name}. ${def.desc}`, 'weather', def.icon);
399:       if (next === 'tempestade') {
400:         audio.play('thunder');
401:         this.player.wet = Math.min(100, this.player.wet + 30);
402:       }
403:     }
404:     this.weatherTimer = randRange(this.world.rng, 90, 300);
405:     this.applyWeatherAudio();
406:   }
407: 
408:   applyWeatherAudio() {
409:     const def = WEATHERS[this.weather] || WEATHERS.limpo;
410:     const wet = def.wet;
411:     audio.setRain(wet);
412:   }
413: 
414:   updateAutosave(dt) {
415:     this.autosaveTimer += dt;
416:     if (this.autosaveTimer > 45) {
417:       this.autosaveTimer = 0;
418:       if (this.mode === 'single') this.ui?.autosave();
419:     }
420:   }
