775:       stack.equipped = true;
776:       this.completeObjective('weapon');
777:       this.ui?.notify(`${def.name} equipada.`, 'good', def.icon);
778:     } else if (def.type === 'backpack') {
779:       for (const s of this.player.inventory) if (ITEMS[s.id]?.type === 'backpack') s.equipped = false;
