824:   // ================= SKILLS =================
825:   grantSkill(skill, amount) {
826:     const s = this.player.skills[skill];
827:     if (!s) return;
828:     const mult = 1 + (this.player.xpBonus || 0);
829:     s.xp += amount * mult;
830:     this.addXP(amount * 0.6 * mult);
831:     let leveled = false;
832:     while (s.xp >= s.next) {
833:       s.xp -= s.next;
834:       s.level++;
835:       s.next = this.skillNext(s.level);
836:       leveled = true;
837:       this.ui?.notify(`${SKILLS[skill].name} nível ${s.level}! ${SKILLS[skill].desc}`, 'skill', SKILLS[skill].icon);
838:       audio.play('level');
839:     }
840:     if (leveled) {
841:       this.player.capacity = this.calcCapacity();
842:       this.ui?.refreshSkills?.();
843:     }
844:     if (this.ui) this.ui.hudDirty = true;
845:   }
