941:   // ================= SALVAR =================
942:   serialize() {
943:     const p = this.player;
944:     return {
945:       v: 2, seed: this.seed, difficulty: this.difficulty, mode: 'single',
946:       time: this.time, day: this.day, weather: this.weather, weatherTimer: this.weatherTimer,
947:       clock: this.clock, stats: this.stats, flags: this.flags, objectives: this.objectives,
948:       player: {
949:         name: p.name, background: p.background, x: p.x, y: p.y, angle: p.angle,
950:         health: p.health, maxHealth: p.maxHealth, hunger: p.hunger, thirst: p.thirst,
951:         fatigue: p.fatigue, stamina: p.stamina, maxStamina: p.maxStamina, temp: p.temp,
952:         hygiene: p.hygiene, infection: p.infection, bleed: p.bleed, wet: p.wet, sick: p.sick,
953:         injuries: p.injuries, xp: p.xp, level: p.level, xpNext: p.xpNext, xpBonus: p.xpBonus,
954:         skills: p.skills, inventory: p.inventory.map(s => ({ ...s })), flashlight: p.flashlight,
955:         inVehicleId: p.inVehicle?.id || null,
