441:           hp: s.hp, maxHp: s.maxHp || def.hp, speed: s.speed || def.speed,
442:           damage: s.damage || def.damage, size: s.size || def.size,
443:           state: s.state || 'idle', alert: s.alert || 0, target: null, wander: null,
444:           idleTimer: 2, attackCd: s.attackCd || 0, anim: s.anim || Math.random() * 10,
445:           groanCd: 5, home: { x: s.x, y: s.y }, stuck: 0, trapCd: 0, hitFlash: 0,
446:           lunge: s.lunge || 0, remote: true,
447:         };
448:         this.game.zombies.push(z);
449:         added++;
450:       }
451:       z.tx = s.x; z.ty = s.y;
452:       z.angle = s.angle ?? z.angle;
453:       z.hp = s.hp; z.maxHp = s.maxHp || z.maxHp;
454:       z.state = s.state || z.state; z.alert = s.alert || 0;
