456:       z.lunge = s.lunge || 0; z.remote = true;
457:       if (added === 0 && (Math.abs(z.x - s.x) > 3 || Math.abs(z.y - s.y) > 3)) {
458:         z.x += (s.x - z.x) * 0.25;
459:         z.y += (s.y - z.y) * 0.25;
460:       }
461:     }
462:     for (let i = this.game.zombies.length - 1; i >= 0; i--) {
463:       if (!seen.has(this.game.zombies[i].id)) this.game.zombies.splice(i, 1);
464:     }
